    bool xong_bai_tap = true;
    bool xong_don_phong = false;

    cout << "AND: " << (xong_bai_tap && xong_don_phong) << endl;
    cout << "OR: "  << (xong_bai_tap || xong_don_phong) << endl;
    cout << "NOT: " << (!xong_don_phong) << endl;

    cout << "---" << endl;
    int diem = 0;
    if (diem > 0 && 100 / diem > 5) {
        cout << "An toan, khong crash" << endl;
    } else {
        cout << "Dieu kien sai o ve trai, bo qua ve phai" << endl;
    }

    return 0;
}

